    match &self.allowed_repo_ids {
        AccessScope::Admin => Ok(None),
        AccessScope::Restricted(ids) => {
            if requests_restriction {
                Err(AppError::Authorization)
            } else if ids.len() == 0 {
                Err(AppError::Authorization)
            } else {
                Ok(Some(ids.clone()))
            }
        }
    }
}

