pub fn effective_iat_ms(&self) -> i64 {
    match self.iat_ms {
        Some(ms) => ms,
        None => {
            if self.iat > i64::MAX / 1000 {
                i64::MAX
            } else if self.iat < i64::MIN / 1000 {
                i64::MIN
            } else {
                self.iat * 1000
            }
        }
    }
}

