paths.decode_ticket.code:
fn decode_ticket(bytes: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if b == b'+' {
            out.push(b' ');
            i += 1;
        } else if b == b'%' && i + 2 < bytes.len() {
            match (hex_digit(bytes[i + 1]), hex_digit(bytes[i + 2])) {
                (Some(h), Some(l)) => {
                    push_latin1(&mut out, (h * 16 + l) as u8);
                    i += 3;
                }
                _ => {
                    push_latin1(&mut out, b);
                    i += 1;
                }
            }
        } else {
            push_latin1(&mut out, b);
            i += 1;
        }
    }
    out
}

