            && seg_is(&segments, 2, b"gallery")
            && seg_is(&segments, 3, b"extensionquery")
            && segments.len() <= 4
    } else if seg_is(&segments, 0, b"pypi") {
        is_pypi_xmlrpc_tail(&segments)
    } else {
