    if !seg_is(&segments, 0, b"nuget") {
        return false;
    }
    if !seg_nonempty(&segments, 1) {
        return false;
    }
    if !seg_is(&segments, 2, b"api") || !seg_is(&segments, 3, b"v2") {
        return false;
    }
    if !seg_is(&segments, 4, b"package") {
        return false;
    }
    if segments.len() <= 5 {
        true
    } else if segments[5].len() == 0 {
        segments.len() <= 6
    } else {
        false
    }
}

