paths.percent_decode_bytes.code:
fn percent_decode_bytes(bytes: &[u8]) -> Option<Vec<u8>> {
    let mut decoded = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' {
            if i + 1 >= bytes.len() {
                return None;
            }
            let hi = match percent_hex_val(bytes[i + 1]) {
                Some(h) => h,
                None => return None,
            };
            if i + 2 >= bytes.len() {
                return None;
            }
            let lo = match percent_hex_val(bytes[i + 2]) {
                Some(l) => l,
                None => return None,
            };
            decoded.push((hi << 4) | lo);
            i += 3;
        } else {
            decoded.push(bytes[i]);
            i += 1;
        }
    }
    Some(decoded)
}

