strs.utf8_seq.code:
fn utf8_seq(s: &[u8], i: usize) -> usize {
    let n = s.len() - i;
    let b = s[i];
    if b < 0x80 {
        return 1;
    }
    if b >= 0xC2 && b <= 0xDF {
        return if n >= 2 && is_cont_byte(s[i + 1]) { 2 } else { 0 };
    }
    if b >= 0xE0 && b <= 0xEF {
        if n < 3 {
            return 0;
        }
        let c = s[i + 1];
        let ok1 = if b == 0xE0 {
            c >= 0xA0 && c <= 0xBF
        } else if b == 0xED {
            c >= 0x80 && c <= 0x9F
        } else {
            is_cont_byte(c)
        };
        return if ok1 && is_cont_byte(s[i + 2]) { 3 } else { 0 };
    }
    if b >= 0xF0 && b <= 0xF4 {
        if n < 4 {
            return 0;
        }
        let c = s[i + 1];
        let ok1 = if b == 0xF0 {
            c >= 0x90 && c <= 0xBF
        } else if b == 0xF4 {
            c >= 0x80 && c <= 0x8F
        } else {
            is_cont_byte(c)
        };
        return if ok1 && is_cont_byte(s[i + 2]) && is_cont_byte(s[i + 3]) { 4 } else { 0 };
    }
    0
}

