    while i < self.passwords.len() {
        if bytes_eq(&self.passwords[i].0, username) && bytes_eq(&self.passwords[i].1, password) {
            return match &self.passwords[i].2 {
                Ok(u) => Ok(u.clone()),
                Err(e) => Err(*e),
            };
        }
        i += 1;
    }
    Err(AuthErr::Other)
}

