net.CidrRange.parse.code:
pub fn parse(oracle: &Oracle, s: &[u8]) -> Result<CidrRange, ()> {
    let (addr_str, prefix_str) = match split_once(s, b'/') {
        Some(p) => p,
        None => return Err(()),
    };
    let network = match oracle.parse_ip(&addr_str) {
        Some(ip) => ip,
        None => return Err(()),
    };
    let prefix_len = match parse_u8(&prefix_str) {
        Some(p) => p,
        None => return Err(()),
    };
    let max_prefix = match network {
        IpAddr::V4(_) => 32,
        IpAddr::V6(_) => 128,
    };
    if prefix_len > max_prefix {
        return Err(());
    }
    Ok(CidrRange { network, prefix_len })
}

net.decimal_from.code:
fn decimal_from(s: &[u8], start: usize) -> Option<u8> {
    let mut v: u32 = 0;
    let mut i = start;
    while i < s.len() {
        let b = s[i];
        if b < b'0' || b > b'9' {
            return None;
        }
        v = v * 10 + (b - b'0') as u32;
        if v > 255 {
            return None;
        }
        i += 1;
    }
    Some(v as u8)
}

