token_expiry.default_policy.code:
pub fn default_policy() -> Policy {
    Policy {
        require_expiration: false,
        min_days: 1,
        max_days: 90,
        default_days: Some(90),
        apply_to_service_accounts: false,
    }
}

token_expiry.validate.code:
pub fn validate(policy: &Policy) -> Result<(), PolicyError> {
    if policy.min_days < 1 {
        return Err(PolicyError::Minimum);
    }
    if policy.max_days < policy.min_days {
        return Err(PolicyError::ReversedRange);
    }
    if policy.max_days > 3650 {
        return Err(PolicyError::Maximum);
    }
    if let Some(days) = policy.default_days {
        if days < policy.min_days || days > policy.max_days {
            return Err(PolicyError::DefaultRange);
        }
    }
    Ok(())
}

token_expiry.resolve_expiry.code:
pub fn resolve_expiry(
    policy: &Policy,
    requested_days: Option<i64>,
    is_service_account: bool,
) -> Result<ResolvedExpiry, PolicyError> {
    if !policy.require_expiration || (is_service_account && !policy.apply_to_service_accounts) {
        return Ok(ResolvedExpiry {
            expires_in_days: requested_days,
            policy_applied: false,
        });
    }
    match requested_days {
        None => match policy.default_days {
            Some(days) => Ok(ResolvedExpiry {
                expires_in_days: Some(days),
                policy_applied: true,
            }),
            None => Err(PolicyError::Required),
        },
        Some(days) if days < policy.min_days || days > policy.max_days => {
            Err(PolicyError::RequestedRange)
        }
        Some(days) => Ok(ResolvedExpiry {
            expires_in_days: Some(days),
            policy_applied: true,
        }),
    }
}

totp_policy.totp_login_requirement.code:
pub fn totp_login_requirement(policy: TotpPolicy, subject: TotpSubject) -> TotpLoginRequirement {
    if subject.totp_enabled {
        return TotpLoginRequirement::ChallengeExisting;
    }
    if subject.is_service_account {
        return TotpLoginRequirement::NotRequired;
    }
    if subject.auth_provider != AuthProvider::Local {
        return TotpLoginRequirement::NotRequired;
    }
    match policy {
        TotpPolicy::Disabled => TotpLoginRequirement::NotRequired,
        TotpPolicy::RequiredForAdmins if !subject.is_admin => TotpLoginRequirement::NotRequired,
        TotpPolicy::RequiredForAdmins | TotpPolicy::RequiredForAll => {
            TotpLoginRequirement::EnrollmentRequired
        }
    }
}

totp_policy.policy_requires_totp.code:
pub fn policy_requires_totp(policy: TotpPolicy, subject: TotpSubject) -> bool {
    matches!(
        totp_login_requirement(policy, TotpSubject { totp_enabled: false, ..subject }),
        TotpLoginRequirement::EnrollmentRequired
    )
}

totp_policy.check_policy_activation.code:
pub fn check_policy_activation(
    current: TotpPolicy,
    requested: TotpPolicy,
    pinned_by_env: bool,
    actor_totp_enabled: bool,
) -> Result<(), PolicyActivationRefusal> {
    if pinned_by_env {
        return Err(PolicyActivationRefusal::PinnedByEnvironment);
    }
    if !is_tightening(current, requested) {
        return Ok(());
    }
    if actor_totp_enabled { Ok(()) } else { Err(PolicyActivationRefusal::ActorNotEnrolled) }
}

totp_policy.is_tightening.code:
pub fn is_tightening(current: TotpPolicy, requested: TotpPolicy) -> bool {
    strictness(requested) > strictness(current)
}

totp_policy.strictness.code:
pub fn strictness(policy: TotpPolicy) -> u8 {
    match policy {
        TotpPolicy::Disabled => 0,
        TotpPolicy::RequiredForAdmins => 1,
        TotpPolicy::RequiredForAll => 2,
    }
}

totp_policy.is_enforcing.code:
pub fn is_enforcing(policy: TotpPolicy) -> bool {
    !matches!(policy, TotpPolicy::Disabled)
}

